-- v3: olay kartı tepkileri, yeni kriz kartları, oda dönem uzunluğu
alter table public.rooms add column if not exists rounds int;
update public.cards set options = '[{"label": "Festivali bir hafta uzat", "cost": -25000, "icon": "🍇", "effects": {"social": 3}}, {"label": "Sponsorluğu iş insanına ver", "cost": 15000, "icon": "🤝", "effects": {"suspicion": 4, "businessman_cash": 40000}, "desc": "Kasaya para girer, afişlerde onun adı yazar."}, {"label": "Planlandığı gibi bitir", "cost": 0, "icon": "✓", "effects": {}}]'::jsonb where type = 'event' and title = 'Bağ Bozumu Festivali';
