insert into public.cards (id, type, title, description, options, budget_effect) values ('8fe696ff-7a7e-5d6b-9be0-be85a51a1b64', 'crisis', 'Otopark Krizi', 'Çarşıda park yeri kalmadı. Esnaf müşterilerin AVM''ye kaçtığını söylüyor, kaldırımlar araçlarla dolu.', '[{"label": "Katlı otopark yap", "cost": -90000, "icon": "🅿️", "effects": {"transport": 5, "social": 1}}, {"label": "Çarşıyı yayalaştır, aktarma otoparkı kur", "cost": -40000, "icon": "🚶", "effects": {"transport": 2, "health": 2, "social": -1}}, {"label": "Otoparkları özel şirkete devret", "cost": 50000, "icon": "💳", "effects": {"transport": 2, "suspicion": 8, "businessman_cash": 80000}}]'::jsonb, 0) on conflict (id) do nothing;
insert into public.cards (id, type, title, description, options, budget_effect) values ('3e537532-2904-5f94-ad59-65b477475336', 'crisis', 'Sokak Hayvanları Tartışması', 'Bir çocuğun ısırılmasının ardından mahalle ikiye bölündü. Hayvanseverler ve veliler belediye önünde.', '[{"label": "Barınak ve veteriner kliniği kur", "cost": -45000, "icon": "🐕", "effects": {"health": 2, "social": 3}}, {"label": "Kısırlaştırma ve aşı kampanyası", "cost": -20000, "icon": "💉", "effects": {"health": 1, "social": 2}}, {"label": "Hayvanları ilçe dışına bıraktır", "cost": -5000, "icon": "🚚", "effects": {"social": -5, "security": 1}}]'::jsonb, 0) on conflict (id) do nothing;
insert into public.cards (id, type, title, description, options, budget_effect) values ('5dbf6943-b1d3-57f1-a6f5-86ae8b6bafac', 'crisis', 'Elektrik Zammı Protestosu', 'Faturalar iki katına çıktı. Dar gelirli mahallelerde kaçak bağlantılar artıyor, gece eylemleri başladı.', '[{"label": "Dar gelirliye sosyal tarife", "cost": -60000, "icon": "🧾", "effects": {"social": 5}}, {"label": "Belediye binalarına güneş paneli", "cost": -80000, "icon": "☀️", "effects": {"social": 1, "health": 1}, "desc": "Uzun vadede fatura yükü azalır."}, {"label": "Kaçak bağlantılara göz yum", "cost": 0, "icon": "🔌", "effects": {"social": 2, "security": -3, "suspicion": 4}}]'::jsonb, 0) on conflict (id) do nothing;
insert into public.cards (id, type, title, description, options, budget_effect) values ('a0eb19bc-5468-5831-b23a-0b05119e2169', 'crisis', 'Siber Saldırı', 'Belediyenin bütün bilgisayarları fidye yazılımıyla kilitlendi. Ruhsat, su faturası ve otobüs kartı sistemleri çalışmıyor.', '[{"label": "Fidyeyi gizlice öde", "cost": -70000, "icon": "💸", "effects": {"security": 1, "suspicion": 6}}, {"label": "Sistemi sıfırdan kur", "cost": -90000, "icon": "🛡️", "effects": {"security": 4}}, {"label": "Yedeklerle idare et, hizmet aksasın", "cost": -10000, "icon": "💾", "effects": {"social": -3, "transport": -2}}]'::jsonb, 0) on conflict (id) do nothing;
insert into public.cards (id, type, title, description, options, budget_effect) values ('9018ceb7-47a7-51f3-b911-f18ecd70b9fd', 'crisis', 'Kentsel Dönüşüm Teklifi', 'Bir müteahhit depreme dayanıksız eski mahalleyi yıkıp yeniden yapmayı teklif ediyor. Mahalleli evlerini kaybetmekten korkuyor.', '[{"label": "Mahalleliyle birlikte, oylamayla yap", "cost": -10000, "icon": "🗳️", "effects": {"social": 2, "security": 3}}, {"label": "Projeyi müteahhide devret", "cost": 80000, "icon": "🏗️", "effects": {"security": 3, "social": -4, "suspicion": 10, "businessman_cash": 150000}}, {"label": "Teklifi reddet", "cost": 0, "icon": "✋", "effects": {"security": -2}}]'::jsonb, 0) on conflict (id) do nothing;
insert into public.cards (id, type, title, description, options, budget_effect) values ('4cc62835-06bd-5c29-bcda-35383b3688b3', 'crisis', 'Semt Pazarı Taşınıyor', 'Trafik gerekçesiyle semt pazarının şehir dışına taşınması gündemde. Pazarcılar ve emekliler karşı çıkıyor.', '[{"label": "Yerinde kapalı pazar yeri yap", "cost": -60000, "icon": "🧺", "effects": {"social": 3, "health": 2}}, {"label": "Pazar eski yerinde kalsın", "cost": 0, "icon": "📍", "effects": {"transport": -3}}, {"label": "Pazar alanını AVM''ye sat", "cost": 40000, "icon": "🏬", "effects": {"social": -4, "suspicion": 6, "businessman_cash": 100000}}]'::jsonb, 0) on conflict (id) do nothing;
insert into public.cards (id, type, title, description, options, budget_effect) values ('5deb7ed8-23c8-5c54-907b-5571076399f2', 'crisis', 'Okul Servisi Kazası', 'Bir okul servisi kırmızı ışıkta geçip kaza yaptı. Kimse ağır yaralanmadı ama veliler ayakta.', '[{"label": "Belediye okul servisi hattı kur", "cost": -55000, "icon": "🚌", "effects": {"education": 2, "transport": 3, "security": 2}}, {"label": "Servis denetimlerini sıkılaştır", "cost": -10000, "icon": "📋", "effects": {"security": 3}}, {"label": "Bütün servisleri tek firmaya ihale et", "cost": -5000, "icon": "📝", "effects": {"transport": 1, "suspicion": 7, "businessman_cash": 60000}}]'::jsonb, 0) on conflict (id) do nothing;
insert into public.cards (id, type, title, description, options, budget_effect) values ('9c8d106f-b8b0-5da6-8f95-c8e7d301039f', 'crisis', 'Hava Kirliliği Alarmı', 'Kış ayında partikül madde ölçümü sınırın üç katına çıktı. Astım hastaları acile koşuyor.', '[{"label": "Doğalgaza geçişe destek ver", "cost": -80000, "icon": "🔥", "effects": {"health": 6}}, {"label": "Sanayiye gece üretim yasağı koy", "cost": -10000, "icon": "🏭", "effects": {"health": 4, "businessman_cash": -80000}}, {"label": "Ölçüm istasyonunu parka taşı", "cost": 0, "icon": "📟", "effects": {"health": -2, "suspicion": 8}, "desc": "Rakamlar düzelir, hava düzelmez."}]'::jsonb, 0) on conflict (id) do nothing;
